REngineAction.script:
is_domo <- TRUE

library(dplyr)

if( is_domo ){
    library(domomagic)
    sales_activity <- read.dataframe('Sales Team Activity')    
}else{
    sales_activity <- rdomoapi::ds_get('879e1af7-a273-419b-bec8-18d5eff24b0f',r_friendly_names=FALSE)
}

sa_rel <- sales_activity %>% select(`activity id`,`dedicated pitches`) %>%
    filter(`dedicated pitches` != '')

ff <- function(activity_id,pitches){
    pp <- data.frame(pitch=unlist(pitches))
    pp$activity_id <- activity_id
    return(pp)
}

account_w_pitches <- mapply(ff,as.list(sa_rel$`activity id`),strsplit(sa_rel$`dedicated pitches`,';'),SIMPLIFY=FALSE) %>%
    bind_rows()

if( is_domo ){
    out <- account_w_pitches
    if( nrow(account_w_pitches) == 0 ){
        out <- data.frame(pitch='test',activity_id='test')
    }
    write.dataframe(out)
}
